function validate([operations, args]) {
  if (!Array.isArray(operations) || !Array.isArray(args) || operations.length !== args.length) return 'operations and arguments need the same length.';
  if (operations[0] !== 'Skiplist' || !Array.isArray(args[0]) || args[0].length !== 0) return 'Start with Skiplist() and no arguments.';
  if (operations.length - 1 > 50000) return 'At most 5 * 10^4 calls to search, add and erase.';
  for (let i = 1; i < operations.length; i++) {
    if (!['search', 'add', 'erase'].includes(operations[i])) return 'Only search, add and erase can follow the constructor.';
    const a = args[i];
    if (!Array.isArray(a) || a.length !== 1) return `${operations[i]} takes exactly one number.`;
    if (!Number.isInteger(a[0]) || a[0] < 0 || a[0] > 20000) return 'Every number is a whole number from 0 to 2 * 10^4.';
  }
  return null;
}

