class Skiplist {
  constructor() {
    this.maxLevel = 16;
    this.head = { val: -1, next: new Array(this.maxLevel).fill(null) };
    this.level = 1;
  }

  predecessors(target) {
    const update = new Array(this.maxLevel).fill(this.head);
    let node = this.head;
    for (let i = this.level - 1; i >= 0; i--) {
      while (node.next[i] !== null && node.next[i].val < target) {
        node = node.next[i];
      }
      update[i] = node;
    }
    return update;
  }

  search(target) {
    const update = this.predecessors(target);
    const candidate = update[0].next[0];
    return candidate !== null && candidate.val === target;
  }

  add(num) {
    const update = this.predecessors(num);
    let height = 1;
    while (height < this.maxLevel && Math.random() < 0.5) {
      height++;
    }
    this.level = Math.max(this.level, height);
    const node = { val: num, next: new Array(height).fill(null) };
    for (let i = 0; i < height; i++) {
      node.next[i] = update[i].next[i];
      update[i].next[i] = node;
    }
  }

  erase(num) {
    const update = this.predecessors(num);
    const node = update[0].next[0];
    if (node === null || node.val !== num) {
      return false;
    }
    for (let i = 0; i < node.next.length; i++) {
      update[i].next[i] = node.next[i];
    }
    while (this.level > 1 && this.head.next[this.level - 1] === null) {
      this.level--;
    }
    return true;
  }
}

