class Skiplist {
  constructor() {
    this.values = [];
  }
  search(target) {
    return this.values.includes(target);
  }
  add(num) {
    this.values.push(num);
  }
  erase(num) {
    const at = this.values.indexOf(num);
    if (at < 0) return false;
    this.values.splice(at, 1);
    return true;
  }
}

