function generate(rand, size) {
  const int = (low, high) => low + Math.floor(rand() * (high - low + 1));
  const large = size === 'large';
  const calls = large ? 499 : int(1, 18);
  const top = large ? (rand() < 0.5 ? 20000 : int(50, 400)) : (rand() < 0.7 ? int(1, 6) : 20000);
  const addRate = 0.3 + rand() * 0.3;
  const searchRate = 0.15 + rand() * 0.25;
  const stored = [];
  const pick = () => (stored.length && rand() < 0.6 ? stored[int(0, stored.length - 1)] : (rand() < 0.1 ? (rand() < 0.5 ? 0 : 20000) : int(0, top)));
  const operations = ['Skiplist'];
  const args = [[]];
  for (let i = 0; i < calls; i++) {
    const roll = rand();
    const value = pick();
    if (roll < addRate) {
      operations.push('add');
      stored.push(value);
    } else if (roll < addRate + searchRate) {
      operations.push('search');
    } else {
      operations.push('erase');
      const at = stored.indexOf(value);
      if (at >= 0) stored.splice(at, 1);
    }
    args.push([value]);
  }
  return [operations, args];
}
